// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {CVXStaker, ICVXBooster, IERC20} from "../src/CVXStaker.sol";

contract InvMutTest is Test {
    CVXStaker c;

    function setUp() public { c = new CVXStaker(address(new __InvMutHandleStub()), IERC20(address(this)), ICVXBooster(address(this)), new address[](0)); }

    function testFuzz_property(address newOwner) public {
        // setUp() deployed c with this test contract as owner (msg.sender in constructor)
        // General rule: transferring ownership to a non-zero newOwner distinct from the
        // current owner makes c.owner() == newOwner afterwards, for EVERY such input.
        vm.assume(newOwner != address(0));
        vm.assume(newOwner != address(this));
        vm.assume(newOwner != address(c));

        vm.prank(address(this));
        c.transferOwnership(newOwner);

        assertTrue(c.owner() == newOwner);
    }
}
